shader_body
{
vec2 d = (vec2(1.0)/uTexSize);
vec3 dx = ( GetPixel(uv+vec2( 1.0 , 0.0 )*d)-GetPixel(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetPixel(uv+vec2( 0.0 , 1.0 )*d)-GetPixel(uv-vec2( 0.0 , 1.0 )*d).xy );
vec2 dz = vec2(dx.y,dy.y) * 3.0;
d = (vec2(1.0)/uTexSize) * 2.0;
dx = ( GetBlur1(uv+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
dz +=vec2(dx.y,dy.y);
vec3 bg = pow(length(dz)*0.8+0,0.7) * 2.0 + GetBlur1(uv).y * 2.0;
ret = bg*vec3(0.2,0.3,0.6);
vec2 uv_swimmer =fract(0.5 + (uv-0.5)+vec2(q19,q20)*vec2(-1, 1.0 ));
ret = mix(ret,vec3( 3.0 , 2.0 , 1.0),GetBlur3(uv_swimmer -vec2(dx.y,dy.y)).x);
ret = mix(ret, 0.0 ,GetBlur2(uv_swimmer-dz).x);
ret = mix(ret,vec3( 0.0 , 0.0 , 0.0),1.5*GetPixel(uv_swimmer).x);
//ret = GetPixel(uv);
//ret = vec3(.7) - ret;
ret.xyz = (ret.r+ret.g+ret.b)/3.0;
if ( ret.x > audioHigh / 4.0) {
ret.xyz = 1;
} else {
ret.xyz = 0;
}
float cuto = 0.1;
if (audioHigh < cuto) {
ret *= mix( 0.0 , 1.0 ,cuto);
}
}

